def read(p): return Path(p).read_text(encoding='utf-8')
def write(p,s): Path(p).write_text(s,encoding='utf-8',newline='\n')
def rep1(p,old,new,label):
    s=read(p); n=s.count(old)
    if n!=1: raise SystemExit(f'{p}: {label}: expected 1, got {n}')
    write(p,s.replace(old,new,1))
def regex1(p,pat,repl,label,flags=re.S):
    s=read(p); out,n=re.subn(pat,repl,s,count=1,flags=flags)
    if n!=1: raise SystemExit(f'{p}: {label}: expected 1, got {n}')
    write(p,out)

